def milutinBinaryTreeWeight : (n : ℕ) → MilutinBinaryWord n → C(Y, ℝ)
  | 0, _ => 1
  | n + 1, w => milutinBinaryTreeWeight n (Fin.init w) *
      if w (Fin.last n) then milutinBinarySplit e he n (Fin.init w)
        else 1 - milutinBinarySplit e he n (Fin.init w)

